def squash(s: str) -> str:
    def esc(c: str) -> str:
        if c == "\\" or "0" <= c <= "9":
            return "\\" + c
        return c

    n = len(s)
    out = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run = j - i
        if run >= 3:
            out.append(str(run))
            out.append(esc(c))
        else:
            piece = esc(c)
            out.append(piece if run == 1 else piece + piece)
        i = j
    return "".join(out)
